# Lease ledger

Repair `ledger.mjs` without changing its public API.

`applyBatch(events)` must be atomic, exactly-once by event id, deterministic for
out-of-order input, and reject id collisions. Events have `id`, `account`,
`delta`, and a positive integer `version`. For each account, unseen events at or
below the committed version are stale and ignored. New events are applied in
version order. A batch that references an unknown account, contains invalid
data, collides with an existing id using a different payload, skips a version,
or makes a balance negative must leave all state unchanged. Replaying an
identical committed event is a no-op. Return the ids newly committed.

Run `node --test public.test.mjs`. Do not read files outside this task directory.
import test from 'node:test';
import assert from 'node:assert/strict';
import { createLedger } from './ledger.mjs';

test('applies a basic event', () => {
  const ledger = createLedger({ a: 10 });
  assert.deepEqual(ledger.applyBatch([{ id: 'e1', account: 'a', delta: 5, version: 1 }]), ['e1']);
  assert.equal(ledger.balance('a'), 15);
  assert.equal(ledger.version('a'), 1);
});

function sameEvent(left, right) {
  return left.id === right.id
    && left.account === right.account
    && Object.is(left.delta, right.delta)
    && left.version === right.version;
}

function normalizeEvent(event) {
  if (event === null || typeof event !== 'object' || Array.isArray(event)) {
    throw new Error('invalid event');
  }

  const { id, account, delta, version } = event;
  if (typeof id !== 'string' || id.length === 0
    || typeof account !== 'string'
    || !Number.isFinite(delta)
    || !Number.isSafeInteger(version)
    || version <= 0) {
    throw new Error('invalid event');
  }

  return Object.freeze({ id, account, delta, version });
}

export function createLedger(openingBalances = {}) {
  const balances = new Map(Object.entries(openingBalances));
  const versions = new Map([...balances.keys()].map((account) => [account, 0]));
  const events = new Map();

  return {
    applyBatch(batch) {
      if (!Array.isArray(batch)) throw new Error('invalid batch');

      const pendingById = new Map();
      for (const rawEvent of batch) {
        const event = normalizeEvent(rawEvent);
        const committed = events.get(event.id);
        const pending = pendingById.get(event.id);

        if (committed && !sameEvent(committed, event)) throw new Error('event id collision');
        if (pending && !sameEvent(pending, event)) throw new Error('event id collision');
        if (committed || pending) continue;
        if (!balances.has(event.account)) throw new Error('unknown account');

        pendingById.set(event.id, event);
      }

      const stagedBalances = new Map(balances);
      const stagedVersions = new Map(versions);
      const pendingByAccount = new Map();
      for (const event of pendingById.values()) {
        if (event.version <= versions.get(event.account)) continue;
        const accountEvents = pendingByAccount.get(event.account) ?? [];
        accountEvents.push(event);
        pendingByAccount.set(event.account, accountEvents);
      }

      const accepted = [];
      for (const account of [...pendingByAccount.keys()].sort()) {
        const accountEvents = pendingByAccount.get(account);
        accountEvents.sort((left, right) => left.version - right.version || left.id.localeCompare(right.id));

        for (const event of accountEvents) {
          const currentVersion = stagedVersions.get(account);
          if (event.version !== currentVersion + 1) throw new Error('version gap');

          const nextBalance = stagedBalances.get(account) + event.delta;
          if (nextBalance < 0) throw new Error('negative balance');

          stagedBalances.set(account, nextBalance);
          stagedVersions.set(account, event.version);
          accepted.push(event);
        }
      }

      for (const [account, balance] of stagedBalances) balances.set(account, balance);
      for (const [account, version] of stagedVersions) versions.set(account, version);
      for (const event of accepted) events.set(event.id, event);
      return accepted.map((event) => event.id);
    },
    balance(account) { return balances.get(account); },
    version(account) { return versions.get(account); },
    event(id) { return events.get(id); },
  };
}
import test from 'node:test';
import assert from 'node:assert/strict';
import { createLedger } from './ledger.mjs';

test('sorts a batch by account version before committing it', () => {
  const ledger = createLedger({ a: 10 });

  assert.deepEqual(ledger.applyBatch([
    { id: 'second', account: 'a', delta: -3, version: 2 },
    { id: 'first', account: 'a', delta: 5, version: 1 },
  ]), ['first', 'second']);
  assert.equal(ledger.balance('a'), 12);
  assert.equal(ledger.version('a'), 2);
});

test('leaves the ledger unchanged when any event in a batch fails', () => {
  const ledger = createLedger({ a: 10 });

  assert.throws(() => ledger.applyBatch([
    { id: 'first', account: 'a', delta: 1, version: 1 },
    { id: 'gap', account: 'a', delta: 1, version: 3 },
  ]));
  assert.equal(ledger.balance('a'), 10);
  assert.equal(ledger.version('a'), 0);
  assert.equal(ledger.event('first'), undefined);
});

test('replays matching events and rejects id collisions', () => {
  const ledger = createLedger({ a: 10 });
  const event = { id: 'e1', account: 'a', delta: 2, version: 1 };

  assert.deepEqual(ledger.applyBatch([event]), ['e1']);
  assert.deepEqual(ledger.applyBatch([event]), []);
  assert.throws(() => ledger.applyBatch([{ ...event, delta: 3 }]));
  assert.equal(ledger.balance('a'), 12);
  assert.equal(ledger.version('a'), 1);
});

test('ignores unseen stale events but rejects a negative staged balance', () => {
  const ledger = createLedger({ a: 2 });
  ledger.applyBatch([{ id: 'e1', account: 'a', delta: 1, version: 1 }]);

  assert.deepEqual(ledger.applyBatch([{ id: 'stale', account: 'a', delta: 100, version: 1 }]), []);
  assert.throws(() => ledger.applyBatch([{ id: 'e2', account: 'a', delta: -4, version: 2 }]));
  assert.equal(ledger.balance('a'), 3);
  assert.equal(ledger.version('a'), 1);
  assert.equal(ledger.event('e2'), undefined);
});
